"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[80868],{37203:e=>{e.exports=JSON.parse('{"tag":{"label":"privacy","permalink":"/tags/privacy","allTagsPath":"/tags","count":17,"items":[{"id":"guides/complete-guide-cookieless-analytics","title":"Complete Guide to Cookieless Analytics 2026","description":"Cookieless analytics captures 100% of visitor data without consent banners: how it works, why cookie-based tools lose 15-60% of EU data, and how to set it up.","permalink":"/guides/complete-guide-cookieless-analytics"},{"id":"compliance/data-subject-rights","title":"Data Subject Rights (DSAR)","description":"How data subject access requests work with Sealmetrics \u2014 why visitor requests cannot be linked to any record, and how account-holder rights are handled.","permalink":"/compliance/data-subject-rights"},{"id":"implementation/tracker/first-party","title":"First-Party Tracker","description":"Serve the Sealmetrics tracker from your own subdomain for maximum ad-blocker resistance: DNS setup, activation, and verification.","permalink":"/implementation/tracker/first-party"},{"id":"faq/index","title":"Frequently Asked Questions (FAQ)","description":"Answers to the most common questions about Sealmetrics, consentless analytics, attribution, implementation, privacy, product features, and legal compliance.","permalink":"/faq/"},{"id":"compliance/gpc-dnt-signals","title":"Global Privacy Control (GPC) and Do Not Track (DNT)","description":"Why Sealmetrics does not respond to GPC or DNT browser signals \u2014 you cannot opt out of a measurement that never tracked you in the first place.","permalink":"/compliance/gpc-dnt-signals"},{"id":"security-privacy/attribution-without-userid","title":"How Attribution Works Without a User-ID","description":"How Sealmetrics attributes traffic and conversions without User-IDs, cookies or cross-session tracking \u2014 last-click attribution read from the URL on every hit.","permalink":"/security-privacy/attribution-without-userid"},{"id":"security-privacy/how-consentless-works","title":"How Consentless Tracking Works","description":"The mechanics of consentless tracking \u2014 four non-identifying variables, isolated hits, a short-lived session marker, and EU-only aggregate storage.","permalink":"/security-privacy/how-consentless-works"},{"id":"security-privacy/country-detection","title":"How Sealmetrics determines the country without using IP addresses","description":"How Sealmetrics detects visitor country from the browser timezone instead of IP addresses \u2014 GDPR-friendly geo data with zero personal data processing.","permalink":"/security-privacy/country-detection"},{"id":"security-privacy/how-we-protect-privacy","title":"How Sealmetrics Protects User Privacy","description":"The concrete protections behind Sealmetrics \u2014 no cookies, no persistent identifiers, no stored IP addresses, EU-only storage and short retention.","permalink":"/security-privacy/how-we-protect-privacy"},{"id":"security-privacy/index","title":"Security & Privacy","description":"How Sealmetrics measures without personal data \u2014 four non-identifying variables, nothing on the device, EU-only storage in Dublin \u2014 with the index of every privacy and security page.","permalink":"/security-privacy/"},{"id":"faq/privacy-technical","title":"Technical Privacy Model","description":"Learn exactly what data Sealmetrics collects, what it does not collect, and how privacy is enforced technically.","permalink":"/faq/privacy-technical"},{"id":"implementation/custom-properties/user-properties","title":"User Segmentation","description":"Segment users by including business attributes in your conversion and microconversion properties.","permalink":"/implementation/custom-properties/user-properties"},{"id":"security-privacy/demdex-net-cookies","title":"What Is demdex.net? The Adobe Cookies in Your Audit","description":"demdex.net belongs to Adobe\'s Experience Cloud ID Service. What the demdex, dextp and dst cookies do, where the requests go, and how to classify them for consent.","permalink":"/security-privacy/demdex-net-cookies"},{"id":"security-privacy/omtrdc-net-requests","title":"What Is omtrdc.net? Adobe\'s Collection Domain, Explained","description":"omtrdc.net is where Adobe Analytics sends every hit. What the requests are, when they fire, why an image GET loses data, and how to check your own site.","permalink":"/security-privacy/omtrdc-net-requests"},{"id":"security-privacy/third-party-analytics-domains","title":"What Is This Domain in My Cookie Audit?","description":"A lookup table of the external domains analytics tools contact \u2014 Adobe, GA4, Mixpanel, PostHog, Piwik PRO and others. Which tool owns each one, and where it resolves.","permalink":"/security-privacy/third-party-analytics-domains"},{"id":"security-privacy/what-we-track","title":"What We Track vs What We Don\u2019t","description":"Field-by-field list of what Sealmetrics records on every hit, how long each field is kept, and what it never collects.","permalink":"/security-privacy/what-we-track"},{"id":"security-privacy/adblocker-bypass","title":"Why Sealmetrics Is Not Blocked by AdBlockers","description":"Learn why Sealmetrics bypasses AdBlockers through 1st-party tracking and a privacy-first architecture that avoids third-party domain blocking.","permalink":"/security-privacy/adblocker-bypass"}],"unlisted":false}}')}}]);